DENYLIST = frozenset( [ 'self', 's', 'cls', 'xrange' ] )

def build_all_list():
  # CRITICAL: harvested names must never shadow Python builtins (e.g.
  # 'object', 'Exception') -- a stubbed 'object' breaks `class X(object)`.
  import builtins
  builtin_names = set( dir( builtins ) )
  seen, out = set(), []
  for n in list( BASELINE_EXPORTS ) + harvest_used_names() + [ 'SparseMemoryImage' ]:
    if not n.isidentifier() or n.startswith( '_' ):
      continue
    if n in builtin_names or n in DENYLIST:
      continue
    if n not in seen:
      seen.add( n )
      out.append( n )
  return out
